// Convert input points to CGAL sites
std::vector<Site_2> sites;
sites.reserve(points.size());
for (const cg3::Point2d& p : points) {
    sites.push_back(Site_2::construct(Point_2(p.x(), p.y())));
}

// Build the Voronoi diagram
VD vd;
vd.insert(sites.begin(), sites.end());

// Extract Voronoi cells
std::vector<std::vector<cg3::Point2d>> result;

// Iterate over all faces of the Voronoi diagram
for (VD::Face_iterator fit = vd.faces_begin(); fit != vd.faces_end(); ++fit) {
    std::vector<cg3::Point2d> cell;

    // Get the halfedge on the boundary of this face
    VD::Halfedge_around_face_circulator hec = fit->incident_halfedges();
    VD::Halfedge_around_face_circulator end = hec;

    do {
        // Get the vertex of this halfedge
        if (!hec->is_bounded()) {
            ++hec;
            continue;
        }

        VD::Vertex_handle vh = hec->vertex();
        if (vh != NULL) {
            Point_2 p = vh->point();
            cell.push_back(cg3::Point2d(CGAL::to_double(p.x()), CGAL::to_double(p.y())));
        }
        ++hec;
    } while (hec != end);

    if (!cell.empty()) {
        result.push_back(cell);
    }
}

return result;

